const GN03_SEA = 6

func gn03_pace() {
    gn03_steps += 1
    if gn03_steps >= 200 {
        gn03_steps = 0
        wait(1)
    }
    while value.cpu_usage >= 70 {
        wait(1)
    }
}

func gn03_height(gn03_col: location, gn03_seed: number) {
    gn03_n = perlin_noise_3d(gn03_col, gn03_seed, 0.1, 2, 2, 0.5)
    return clamp(floor(GN03_SEA + gn03_n * 8), 4, 16)
}

process gn03_terrain(gn03_a: location, gn03_b: location, gn03_seed: number) {
    on_grid(gn03_col, gn03_a, gn03_b) {
        gn03_h = gn03_height(gn03_col, gn03_seed)
        gn03_top = shift_coordinate(gn03_col, gn03_h, type: y)
        set_region(block(stone), gn03_col, gn03_top)
        set_region(block(dirt), shift_coordinate(gn03_top, -2, type: y), gn03_top)
        set_block(gn03_top, block(grass_block))
        if gn03_h < GN03_SEA {
            set_region(block(light_blue_stained_glass), shift_coordinate(gn03_top, 1, type: y), shift_coordinate(gn03_col, GN03_SEA, type: y))
        }
        gn03_pace()
    }
    gn03_cols, gn03_grass, gn03_dirt, gn03_stone, gn03_lo, gn03_hi = 0, 0, 0, 0, 99, 0
    on_grid(gn03_col, gn03_a, gn03_b) {
        gn03_h = gn03_height(gn03_col, gn03_seed)
        gn03_top = shift_coordinate(gn03_col, gn03_h, type: y)
        gn03_cols += 1
        gn03_lo = min(gn03_lo, gn03_h)
        gn03_hi = max(gn03_hi, gn03_h)
        if game.block_equals(block(grass_block), gn03_top) {
            gn03_grass += 1
        }
        if game.block_equals(block(dirt), shift_coordinate(gn03_top, -1, type: y)) {
            gn03_dirt += 1
        }
        if game.block_equals(block(stone), shift_coordinate(gn03_top, -3, type: y)) {
            gn03_stone += 1
        }
        gn03_pace()
    }
    send_message("gn03 столбцов ${gn03_cols} трава ${gn03_grass} земля ${gn03_dirt} камень ${gn03_stone}")
    gn03_ok = gn03_hi - gn03_lo >= 2
    send_message("gn03 перепад ${gn03_ok} высоты ${gn03_lo} ${gn03_hi}")
    gn03_h = gn03_height(gn03_b, gn03_seed)
    gn03_sky = set_location_direction(shift_coordinate(gn03_b, 30, type: y), vec(0, -1, 0))
    ray_trace_result(variable_for_hit_block_location: gn03_hit, start: gn03_sky, max_distance: 40, ray_size: 0, ray_collision_mode: only_blocks)
    gn03_want = floor(get_coordinate(gn03_b, type: y) + gn03_h)
    gn03_got = floor(get_coordinate(gn03_hit, type: y))
    gn03_ok = gn03_want == gn03_got
    send_message("gn03 луч нашёл поверхность ${gn03_ok} ${gn03_want} ${gn03_got}")
    gn03_end = shift_all_coordinates(gn03_b, 0, 18, 0)
    clear_region(gn03_a, gn03_end)
    wait(5)
    gn03_gone = game.block_equals(block(air), shift_coordinate(gn03_a, 2, type: y))
    send_message("gn03 убрано ${gn03_gone}")
}

