game `gn10_undo %player%`: list
game `gn10_redo %player%`: list

func gn10_capture(gn10_a: location, gn10_b: location) {
    gn10_ids = create_list()
    on_grid(gn10_p, gn10_a, gn10_b) {
        gn10_id = get_block_material(gn10_p, value_type: id_with_data)
        if not gn10_id in gn10_ids {
            gn10_ids = append_value(gn10_id)
            `gn10_places %var_local(gn10_id)` = create_list()
        }
        `gn10_places %var_local(gn10_id)` = append_value(gn10_p)
    }
    gn10_taken = create_map()
    for gn10_id in gn10_ids {
        gn10_taken[gn10_id] = `gn10_places %var_local(gn10_id)`
    }
    return gn10_taken
}

func gn10_apply(gn10_what: map) {
    for gn10_put_id: gn10_put_places in gn10_what {
        set_block(gn10_put_places, gn10_put_id)
    }
}

func gn10_step(gn10_a: location, gn10_b: location, gn10_new: block) {
    `gn10_undo %player%` = append_value(gn10_capture(gn10_a, gn10_b))
    `gn10_redo %player%` = create_list()
    set_region(gn10_new, gn10_a, gn10_b)
}

func gn10_undo(gn10_a: location, gn10_b: location) {
    gn10_last = len(`gn10_undo %player%`) - 1
    if gn10_last < 0 {
        return
    }
    gn10_snap = get_list_value(`gn10_undo %player%`, gn10_last)
    `gn10_undo %player%` = remove_list_value_at_index(gn10_dropped, `gn10_undo %player%`, gn10_last)
    `gn10_redo %player%` = append_value(gn10_capture(gn10_a, gn10_b))
    gn10_apply(gn10_snap)
}

func gn10_redo(gn10_a: location, gn10_b: location) {
    gn10_last = len(`gn10_redo %player%`) - 1
    if gn10_last < 0 {
        return
    }
    gn10_snap = get_list_value(`gn10_redo %player%`, gn10_last)
    `gn10_redo %player%` = remove_list_value_at_index(gn10_dropped, `gn10_redo %player%`, gn10_last)
    `gn10_undo %player%` = append_value(gn10_capture(gn10_a, gn10_b))
    gn10_apply(gn10_snap)
}

