func gn12_mix(gn12_a: location, gn12_b: location, gn12_parts: map) {
    gn12_all = create_list()
    on_grid(gn12_p, gn12_a, gn12_b) {
        gn12_all = append_value(gn12_p)
    }
    gn12_all = randomize_list_order(gn12_all)
    gn12_from = 0
    for gn12_id: gn12_percent in gn12_parts {
        gn12_to = round(gn12_from + len(gn12_all) * gn12_percent / 100)
        gn12_cut = trim_list(gn12_all, gn12_from, gn12_to)
        set_block(gn12_cut, gn12_id)
        gn12_from = gn12_to
    }
}

