game `gn13_busy %player%`
game `gn13_stop %player%`

process gn13_bar() {
    while gn13_running == 1 {
        wait(5)
        gn13_percent = floor(gn13_done * 100 / gn13_total)
        set_boss_bar("gn13", "gn13 ${gn13_percent}%", gn13_percent, style: notched_20, color: green)
    }
    remove_boss_bar("gn13")
}

process gn13_work(gn13_a: location, gn13_b: location) {
    gn13_running, gn13_done, gn13_total = 1, 0, 2000
    start gn13_bar(local_variables_mode: share)
    on_grid(gn13_p, gn13_a, gn13_b) {
        if `gn13_stop %player%` == 1 {
            break
        }
        set_block(gn13_p, block(glass))
        gn13_done += 1
        if remainder(gn13_done, 10) == 0 {
            wait(1)
        }
    }
    gn13_running = 0
    gn13_ok = gn13_done < gn13_total
    if `gn13_stop %player%` == 1 {
        send_message("gn13 остановлено ${gn13_ok}")
    } else {
        send_message("gn13 готово")
    }
    purge(["gn13_busy %player%", "gn13_stop %player%"])
    clear_region(gn13_a, gn13_b)
    wait(5)
    gn13_gone = game.block_equals(block(air), gn13_a)
    send_message("gn13 убрано ${gn13_gone}")
}

when player_chat {
    if chat_message_equals("@gn13") {
        cancel_event()
        if `gn13_busy %player%` == 1 {
            send_message("gn13 занято")
            end_thread()
        }
        `gn13_busy %player%` = 1
        gn13_a = shift_coordinate(align_location(value.location, rotation_mode: remove), 8, type: y)
        send_message("gn13 старт")
        start gn13_work(gn13_a, shift_all_coordinates(gn13_a, 19, 4, 19))
    }
    if chat_message_equals("@gn13стоп") {
        cancel_event()
        `gn13_stop %player%` = 1
    }
}
